-- HS-PORT-03 / issue #159: run-level ingest history in the shared database.
--
-- This is a NEW table (not a rename of ingestion_runs) because migrations are
-- forward-only: 001 has already been applied on the production Turso DB, so
-- editing 001 would never re-apply there and fresh vs existing DBs would
-- silently diverge.
--
-- run_id accepts both legacy 36-char UUIDs and the 24-char base64 IDs
-- generated by domain.NewRunID(); CHECK bounds length instead of pinning it.
--
-- status uses the domain.RunStatus vocabulary (running/ok/partial/failed),
-- NOT the legacy 'completed'.
--
-- Retention limit: rows here are small (~1 KB) and bounded (~50/day across
-- all hosts). Recommend pruning older than 90 days (domain.DefaultRetentionDays):
--   DELETE FROM ingest_runs
--   WHERE COALESCE(finished_at, started_at) <
--         strftime('%Y-%m-%dT%H:%M:%SZ','now','-90 days');
-- No automatic prune code in this issue (documented manual step, plan §7/R5).

CREATE TABLE IF NOT EXISTS ingest_runs (
    run_id TEXT PRIMARY KEY CHECK (length(run_id) BETWEEN 1 AND 64),
    origin TEXT NOT NULL DEFAULT '',
    started_at TEXT NOT NULL,
    finished_at TEXT,
    status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'ok', 'partial', 'failed')),
    sources_checked INTEGER NOT NULL DEFAULT 0,
    sources_succeeded INTEGER NOT NULL DEFAULT 0,
    entries_fetched INTEGER NOT NULL DEFAULT 0,
    stories_created INTEGER NOT NULL DEFAULT 0,
    stories_updated INTEGER NOT NULL DEFAULT 0,
    error_summary TEXT NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_ingest_runs_finished ON ingest_runs(finished_at DESC, status);

-- Data-safety carry-over from the legacy table (never written by code; the
-- legacy table only predates this issue). INSERT OR IGNORE keeps this step
-- idempotent if the migration body is re-applied. Legacy status mapping:
-- completed -> ok; failed/running map to themselves.
INSERT OR IGNORE INTO ingest_runs (run_id, origin, started_at, finished_at, status, sources_checked, sources_succeeded, entries_fetched, stories_created, stories_updated, error_summary)
SELECT
    run_id,
    'legacy',
    started_at,
    finished_at,
    CASE status
        WHEN 'completed' THEN 'ok'
        WHEN 'failed' THEN 'failed'
        ELSE 'running'
    END,
    sources_total,
    sources_ok,
    articles_new,
    stories_new,
    0,
    ''
FROM ingestion_runs
WHERE ingestion_runs.run_id IS NOT NULL;

DROP TABLE IF EXISTS ingestion_runs;
